mapper.select:
SELECT id, workflow_instance_id, tenant_id, application_id, task_key, round_no, status,
       decision, comment, completed_by, completed_at, created_at, reminder_at,
       reminded_at, due_at, escalated_at
FROM workflow_tasks
WHERE workflow_instance_id = #{workflowInstanceId, jdbcType=OTHER}
  AND round_no = #{roundNo}
  AND task_key = #{taskKey}
  AND status = 'PENDING'
FOR UPDATE

SELECT EXISTS (
  SELECT 1
  FROM workflow_tasks
  WHERE workflow_instance_id = #{workflowInstanceId, jdbcType=OTHER}
    AND round_no = #{roundNo}
    AND task_key = #{taskKey}
    AND status = 'PENDING'
)

mapper.update:
UPDATE workflow_tasks
SET reminded_at = #{remindedAt}
WHERE id = #{id, jdbcType=OTHER} AND status = 'PENDING' AND reminded_at IS NULL

UPDATE workflow_tasks
SET status = 'ESCALATED', escalated_at = #{escalatedAt}
WHERE id = #{id, jdbcType=OTHER} AND status = 'PENDING' AND escalated_at IS NULL
